const D = { amount:.6, split:.5, energy:.6, speed:1, density:.5, hue:190, scale:1, x:.5, y:.5, style:'datamosh', act:'calm_bursts', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const md=(a,n)=>((a%n)+n)%n, clp=(v,a,b)=>Math.max(a,Math.min(b,v)), lrp=(a,b,t)=>a+(b-a)*t;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
const nz=a=>{const s=Math.sin(a*91.7+P.seed*57.1+11.3)*24634.6345;return s-Math.floor(s);};
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width,H=height,u=Math.min(W,H);
const st=P.style, act=P.act;
const cnv=drawingContext.canvas;
const HUE=md(P.hue,360);
const amt=clp(P.amount,0,1), splitPx=clp(P.split,0,1)*u*0.03;
const oldOp=drawingContext.globalCompositeOperation;

// ---- act dramaturgy: overall glitch arc ----
let arc;
if(act==='storm'){ arc=1.05+0.15*Math.sin(K.t*0.11); }
else if(act==='building'){ arc=clp(0.25+K.intensity*1.0+0.25*Math.sin(K.t*0.045),0,1.3); }
else { arc=clp(0.35+0.45*K.intensity,0,1); } // calm_bursts

// burst: intermittent spikes; NEW seed every ~1.5 beats, plus a continuous-time term so it never fully re-phases at 8s
const bw=Math.floor(K.beat/1.5);
let burst=Math.pow(nz(bw*3.1),4)*2.2;               // mostly ~0, occasional big
burst=clp(burst + 0.25*Math.pow(Math.max(0,Math.sin(K.t*0.37+nz(bw)*6)),6),0,1.4);
const kick=K.pulse*0.5 + A.bass*0.9;
const G=clp((0.14+0.7*amt)*arc*(0.35+burst) + kick*0.28*amt, 0, 1.35);

// ================= content displacement (self-copy from the composited canvas) =================
drawingContext.imageSmoothingEnabled=false;
if(st==='sort'){
  // vertical streak smear: stretch a thin scan row downward into columns (pixel-sort abstraction)
  const nC=Math.round(lrp(3,26,amt)*(0.4+G));
  for(let i=0;i<nC;i++){
    const cw=Math.max(2,u*(0.01+0.05*fr(i*4.1)));
    const cx=md((fr(i*7.7)+K.t*0.03*(1+i%3))*1.2,1.2)*W-W*0.1;
    const srcY=md(fr(i*2.3)+K.t*0.05,1)*H;
    const len=H*(0.15+0.6*fr(i*5.5))*(0.5+G);
    try{ drawingContext.drawImage(cnv, cx, srcY, cw, 2, cx, srcY, cw, len); }catch(e){}
  }
}else if(st==='databend'){
  // rectangular block displacement
  const nB=Math.round(lrp(0,22,amt)*burst);
  for(let i=0;i<nB;i++){
    const bw2=u*(0.06+0.34*nz(bw*7+i)), bh=u*(0.03+0.12*nz(bw*3+i*2));
    const sx=nz(bw*5+i*3)*(W-bw2), sy=nz(bw*11+i)*(H-bh);
    const dx=sx+(nz(bw*13+i)-0.5)*u*0.4*G, dy=sy+(nz(bw*2+i)-0.5)*u*0.05;
    try{ drawingContext.drawImage(cnv, sx,sy,bw2,bh, dx,dy,bw2,bh); }catch(e){}
    if(nz(bw+i*9)<0.4){ drawingContext.globalCompositeOperation='screen'; const hh=md(HUE+nz(i)*180,360); const c=color(hh,90,100,60); drawingContext.fillStyle=c.toString(); drawingContext.fillRect(dx,dy,bw2,bh); drawingContext.globalCompositeOperation='source-over'; }
  }
}else if(st!=='chromatic'&&st!=='mono'){
  // datamosh: horizontal slice tears
  const nSl=Math.round(lrp(1,15,amt)*(0.3+burst*1.2));
  for(let i=0;i<nSl;i++){
    const sh=Math.max(3,u*(0.01+0.09*nz(bw*3+i)));
    const sy=nz(bw*5+i*2)*(H-sh);
    const dx=(nz(bw*7+i)-0.5)*u*0.6*G*(0.5+amt);
    try{ drawingContext.drawImage(cnv, 0,sy,W,sh, dx,sy,W,sh); }catch(e){}
    // rgb split fringe at the leading/trailing seam
    if(splitPx>0.4){ drawingContext.globalCompositeOperation='screen';
      let c=color(0,90,100,55*(0.4+G)); drawingContext.fillStyle=c.toString(); drawingContext.fillRect(dx,sy,splitPx*2,sh);
      c=color(180,90,100,55*(0.4+G)); drawingContext.fillStyle=c.toString(); drawingContext.fillRect(dx+W-splitPx*2,sy,splitPx*2,sh);
      drawingContext.globalCompositeOperation='source-over';
    }
  }
}
drawingContext.imageSmoothingEnabled=true;

// ================= persistent chromatic aberration edge fringe (motion floor, drawn -> visible on flat frames) =================
{
  const wob=Math.sin(K.t*0.8)*0.5+Math.sin(K.t*0.29+1.7)*0.5;   // continuous, non-rephasing
  const off=splitPx*(0.5+0.9*G)+ (0.6+0.6*wob)*u*0.004;
  const bandH=u*(0.03+0.02*Math.sin(K.t*0.5));
  const yc=md(K.t*0.13,1)*H;  // roams so the fringe isn't a static rect on a flat bed
  blendMode(SCREEN); noStroke();
  const a1=(st==='mono')?0:1;
  fill(0,90,100, (14+30*G)*a1); rect(-off*2, yc-bandH, W, bandH*2);
  fill(180,90,100, (14+30*G)*a1); rect(off*2, yc-bandH, W, bandH*2);
  blendMode(BLEND);
}

// ================= data-error color blocks (self-generated flicker; always some, guarantees diff) =================
{
  const nE=Math.round(lrp(2,10,amt)*(0.4+arc));
  const tw=Math.floor(K.t*(4+8*P.speed)); // ~4-12 changes/sec -> never coincides at 8s
  blendMode(st==='mono'?BLEND:SCREEN); noStroke();
  for(let i=0;i<nE;i++){
    if(nz(tw*3+i*7)>0.35+0.4*(1-G)) continue;
    const ex=nz(tw*5+i)*W, ey=nz(tw*7+i*2)*H;
    const ew=u*(0.02+0.16*nz(tw+i*3)), eh=u*(0.004+0.02*nz(tw*2+i));
    const hh=(st==='mono')?HUE:md(HUE+nz(tw+i)*140,360);
    const sat=(st==='mono')?55:85;
    fill(hh,sat,100, 22+40*G); rect(ex,ey,ew,eh);
  }
  blendMode(BLEND);
}

// ================= scanlines + rolling luma band (texture + continuous motion) =================
{
  const scrollY=md(K.t*u*0.08*(1+P.speed*0.3),4);   // fine scanlines scroll continuously
  blendMode(MULTIPLY); stroke(0,0,0, (st==='mono'?55:32)); strokeWeight(1);
  for(let y=-scrollY;y<H;y+=4) line(0,y,W,y);
  blendMode(SCREEN);
  const by=md(K.t*u*0.19,H*1.25)-H*0.12;              // bright tracking band rolls
  const bh2=u*(0.05+0.03*Math.sin(K.t*0.6));
  noStroke(); fill((st==='mono')?HUE:190, (st==='mono')?35:14, 100, 8+10*G);
  rect(0,by,W,bh2);
  blendMode(BLEND);
}

// ================= mono style: chiaroscuro duotone wash (no rgb split, form from light) =================
if(st==='mono'){
  blendMode(MULTIPLY); noStroke();
  const vig=drawingContext.createRadialGradient(P.x*W,P.y*H,u*0.1, P.x*W,P.y*H,u*0.85);
  vig.addColorStop(0,'rgba(255,255,255,0)'); vig.addColorStop(1,'rgba(0,0,0,0.55)');
  drawingContext.fillStyle=vig; drawingContext.fillRect(0,0,W,H);
  blendMode(SCREEN); fill(HUE,45,100,10+14*G); rect(0,0,W,H*0.5);
  blendMode(BLEND);
}

blendMode(BLEND); drawingContext.globalCompositeOperation=oldOp; drawingContext.imageSmoothingEnabled=true; drawingContext.shadowBlur=0; noStroke(); noFill();
